const output = $input.first().json.output ?? '';
let cleaned = output.trimStart();
let safety = 0;
while (cleaned.startsWith('[{') && safety++ < 5) {
  const end = cleaned.indexOf('}]');
  if (end === -1) break;
  cleaned = cleaned.slice(end + 2).trimStart();
}
const finalOutput = cleaned.trim() || output;

// Extraire prix TTC depuis la réponse de l'agent
const pm = finalOutput.match(/(\d[\d\s]{1,6}\d)\s*€\s*TTC/i)
  || finalOutput.match(/TTC[\s:]*([\d\s]{3,8})/i);
const prix_ttc = pm ? parseInt(pm[1].replace(/\s/g, '')) : null;
const has_devis = prix_ttc !== null && prix_ttc > 200;

return [{ json: { output: finalOutput, prix_ttc, has_devis } }];

const rawInput = $input.first().json.input ?? '{}';
let _p = {};
try { _p = JSON.parse(rawInput); } catch { _p = {}; }
const slots = _p.slots ?? {};
const type = _p.type ?? 'confirmation';

const {
  villeDepart = '?',
  villeArrivee = '?',
  dateDepart,
  heureDepart,
  passagers,
  allerRetour
} = slots;

// Formater date lisible
let dateStr = '';
if (dateDepart) {
  const d = new Date(dateDepart);
  dateStr = d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' });
}

let message = '';

if (type === 'confirmation') {
  const parts = [`Trajet noté : ${villeDepart} → ${villeArrivee}`];
  if (dateStr) parts.push(`le ${dateStr}`);
  if (heureDepart) parts.push(`à ${heureDepart}`);
  if (passagers) parts.push(`pour ${passagers} passager${passagers > 1 ? 's' : ''}`);
  if (allerRetour !== undefined) parts.push(allerRetour ? '(aller-retour)' : '(aller simple)');
  message = parts.join(', ') + '.';

} else if (type === 'accueil') {
  message = `Bonjour ! Je suis l'agent NeoTravel. J'ai bien noté votre demande — laissez-moi quelques secondes pour analyser votre trajet.`;

} else if (type === 'devis_pret') {
  message = `Très bien, je prépare votre devis détaillé pour ${villeDepart} → ${villeArrivee}. Souhaitez-vous le recevoir par email, ou qu'un conseiller vous rappelle pour le valider ?`;
}

const complete = !['?'].includes(villeDepart) && !['?'].includes(villeArrivee);

return [{ json: { message, complete } }];

const rawInput = $input.first().json.input ?? '{}';
let _p = {};
try { _p = JSON.parse(rawInput); } catch { _p = {}; }
const txt = String(_p.message ?? '').toLowerCase();
const slots = _p.slots ?? {};
const req = ['villeDepart','villeArrivee','dateDepart','allerRetour','passagers','email'];

if (!slots.dateDepart) {
  const MOIS = {'janvier':1,'fevrier':2,'mars':3,'avril':4,'mai':5,'juin':6,'juillet':7,'aout':8,'septembre':9,'octobre':10,'novembre':11,'decembre':12};
  const JMAX = [0,31,28,31,30,31,30,31,31,30,31,30,31];
  const dtxt = txt.match(/(\d{1,2})\s+(janvier|f[ée]vrier|mars|avril|mai|juin|juillet|ao[uû]t|septembre|octobre|novembre|d[ée]cembre)(?:\s+(\d{4}))?/);
  if (dtxt) {
    const jour = parseInt(dtxt[1]);
    const moisStr = dtxt[2].toLowerCase().replace(/[éè]/g,'e').replace(/û/,'u');
    const moisNum = MOIS[moisStr];
    const annee = dtxt[3] ? parseInt(dtxt[3]) : new Date().getFullYear();
    if (moisNum) {
      const biss = annee%4===0 && (annee%100!==0||annee%400===0);
      const max = moisNum===2 && biss ? 29 : JMAX[moisNum];
      if (jour < 1 || jour > max) {
        const req2 = ['villeDepart','villeArrivee','dateDepart','allerRetour','passagers','email'];
        return JSON.stringify({ hors_domaine:false, hors_france:false, debrayage:false, date_invalide:true, slots, missing:req2.filter(k=>slots[k]==null||slots[k]===undefined), complete:false });
      }
      slots.dateDepart = `${annee}-${String(moisNum).padStart(2,'0')}-${String(jour).padStart(2,'0')}`;
    }
  }
}

const ABROAD = /\b(espagne|spain|madrid|barcelone|italie|italy|rome|milan|allemagne|germany|berlin|munich|royaume.uni|uk|london|londres|belgique|belgium|bruxelles|suisse|switzerland|gen[eè]ve|zurich|portugal|lisbonne|porto|pays.bas|amsterdam|luxembourg|autriche|vienne|pologne|varsovie|budapest|maroc|casablanca|rabat|alg[eé]rie|alger|tunisie|tunis|s[eé]n[eé]gal|dakar|abidjan|cameroun|canada|[eé]tats.unis|usa|new.york|dubai|[eé]mirats|qatar|chine|japon|tokyo|inde|international|[eé]tranger)\b/i;
const hors_france = ABROAD.test(slots.villeDepart || '') || ABROAD.test(slots.villeArrivee || '') || ABROAD.test(txt);

const missing = req.filter(k => slots[k] == null || slots[k] === undefined);
return JSON.stringify({ hors_domaine:false, hors_france, debrayage:false, date_invalide:false, slots, missing, complete:missing.length===0 });

const wb = $('Webhook2').first().json.body ?? {};
const sessionId = wb.sessionId ?? 'NT-' + Date.now();
const userMsg = wb.message ?? '';
const agentOut = $('Nettoyer sortie1').first().json.output ?? '';
const prix_ttc = $('Nettoyer sortie1').first().json.prix_ttc ?? 0;
const now = new Date().toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' });
const refDevis = 'NT-' + Date.now().toString(36).toUpperCase().slice(-6);

const html = `<!DOCTYPE html>
<html lang='fr'><head><meta charset='UTF-8'>
<style>
body{font-family:Arial,sans-serif;color:#0E1C2B;margin:0;padding:40px}
