.hd h1{margin:0;font-size:22px}.hd p{margin:4px 0 0;color:#C2E812;font-size:13px}
.ref{font-size:12px;color:#888;margin-bottom:18px}
.sec{background:#f8f9fa;border-radius:8px;padding:18px 22px;margin-bottom:16px}
.sec h2{margin:0 0 10px;font-size:15px;border-bottom:2px solid #C2E812;padding-bottom:6px}
.row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #eee;font-size:13px}
.row:last-child{border-bottom:none}.lbl{color:#666}.val{font-weight:600}
.pbox{background:#0E1C2B;color:#fff;border-radius:8px;padding:24px;text-align:center;margin:18px 0}
.amt{font-size:38px;font-weight:700;color:#C2E812}.sub{font-size:13px;color:#aaa;margin-top:4px}
.ft{text-align:center;font-size:11px;color:#999;margin-top:24px;border-top:1px solid #eee;padding-top:14px}
</style></head><body>
<div class='hd'><h1>NeoTravel — Devis de transport de groupe</h1><p>Location d'autocar, minibus et bus privé avec chauffeur</p></div>
<div class='ref'>Référence : ${refDevis} · Date : ${now}</div>
<div class='sec'><h2>Détail de la demande</h2>
<div class='row'><span class='lbl'>Demande client</span><span class='val'>${userMsg.slice(0,140)}</span></div>
<div class='row'><span class='lbl'>Réponse agent</span><span class='val' style='font-size:12px;max-width:60%;text-align:right'>${agentOut.slice(0,280)}</span></div>
</div>
<div class='pbox'>
  <div style='font-size:13px;margin-bottom:8px'>TARIF INDICATIF TTC</div>
  <div class='amt'>${prix_ttc.toLocaleString('fr-FR')} €</div>
  <div class='sub'>Chauffeur et carburant inclus · Hors péages</div>
</div>
<div class='sec'><h2>Conditions</h2>
<div class='row'><span class='lbl'>TVA</span><span class='val'>10 %</span></div>
<div class='row'><span class='lbl'>Validité</span><span class='val'>30 jours</span></div>
<div class='row'><span class='lbl'>Acompte</span><span class='val'>30 % à la réservation</span></div>
<div class='row'><span class='lbl'>Annulation gratuite</span><span class='val'>Jusqu'à J−15</span></div>
</div>
<div class='ft'>NeoTravel · 09 80 40 04 84 · contact@neotravel.fr<br>
Ce devis est indicatif — distance et tarif confirmés avant l'envoi du devis définitif.</div>
</body></html>`;

// PDF via Gotenberg (docker run -p 3001:3000 gotenberg/gotenberg:8)
let pdfBase64 = null;
let pdfOk = false;
try {
  const form = new FormData();
  form.append('files', new Blob([html], { type: 'text/html' }), 'index.html');
  const pr = await fetch('http://localhost:3001/forms/chromium/convert/html', {
    method: 'POST', body: form, signal: AbortSignal.timeout(15000)
  });
  if (pr.ok) {
    pdfBase64 = Buffer.from(await pr.arrayBuffer()).toString('base64');
    pdfOk = true;
  }
} catch (_) { /* Gotenberg non disponible */ }

return [{ json: { html, refDevis, sessionId, userMsg, agentOut, prix_ttc, pdfBase64, pdfOk } }];
